<?php
declare(strict_types=1);
$root=dirname(__DIR__);$fails=[];$ok=function(bool $v,string $m)use(&$fails){echo($v?'PASS':'FAIL')." — $m\n";if(!$v)$fails[]=$m;};
$version=trim((string)file_get_contents($root.'/VERSION'));
$sw=(string)file_get_contents($root.'/public_html/service-worker.js');
$flip=(string)file_get_contents($root.'/public_html/assets/reader-flip.js');
$reader=(string)file_get_contents($root.'/public_html/assets/reader.js');
$css=(string)file_get_contents($root.'/public_html/assets/reader.css');
$app=(string)file_get_contents($root.'/app/App.php');
$settings=(string)file_get_contents($root.'/app/Services/SettingsCatalog.php');
$view=(string)file_get_contents($root.'/app/Core/View.php');
$manifest=json_decode((string)file_get_contents($root.'/manifest.json'),true);
$android=(string)file_get_contents($root.'/mobile-android/app/build.gradle');
$main=(string)file_get_contents($root.'/mobile-android/app/src/main/java/in/digiti/epdi/MainActivity.java');
$ok(version_compare($version,'2.0.2.0','>='),'VERSION remains at or above v2.0.2.0');
$ok(str_contains($sw,"const VERSION='epdi-v{$version}';")&&!str_contains($sw,'?v=2.0.1.9'),'Service Worker namespace and shell versions aligned');
$ok(is_array($manifest)&&($manifest['version']??'')===$version&&($manifest['database_migration']??true)===false,'release manifest aligned and schema-free');
$ok(is_file($root.'/public_html/assets/reader-flip.js')&&str_contains($flip,"validModes=['flip','page','continuous']"),'Flip/Page/Continuous adapter packaged');
$ok(str_contains($flip,'flip-drag')&&str_contains($flip,'reader-turn-sheet')&&str_contains($flip,'setTurnProgress'),'interactive drag page turn packaged');
$ok(str_contains($flip,'s[s.length-1]')&&str_contains($flip,'syncNavAvailability'),'odd final spread stops cleanly without phantom Next turn');
$ok(str_contains($flip,'flip-swipe-low-power')&&str_contains($flip,'lowPower:slowDevice()'),'low-power/reduced-motion swipe fallback remains navigable');
$ok(str_contains($flip,"'edge-click'")&&str_contains($flip,"addEventListener('dblclick'"),'edge click turn + double-click zoom arbitration packaged');
$ok(str_contains($flip,'spreadFor')&&str_contains($flip,'flipDesktopSpread')&&str_contains($flip,'flipTabletSpread'),'desktop/tablet spread policy packaged');
$ok(str_contains($flip,'IntersectionObserver')&&str_contains($flip,'reader-continuous-page'),'continuous view is lazy/viewport driven');
$ok(str_contains($flip,'prefers-reduced-motion')&&str_contains($flip,'saveData')&&str_contains($flip,'deviceMemory'),'low-power/reduced-motion fallback packaged');
$ok(!str_contains($flip,'cdn.jsdelivr')&&!str_contains($flip,'unpkg.com'),'Reader runtime has no external CDN dependency');
$ok(str_contains($reader,'window.EpdiReader=')&&str_contains($reader,'window.EpdiReaderViews?.sync?.()')&&str_contains($reader,'pageChanged?.()'),'canonical Reader exposes adapter API and interaction arbitration');
$ok(str_contains($reader,'zoomAtNormalized')&&str_contains($flip,'zoomFromPaperPoint'),'two-page double-tap zoom targets the tapped newspaper page');
$ok(str_contains($settings,"'reader.default_view'")&&str_contains($settings,"'reader.flip_desktop_spread'")&&str_contains($settings,"'reader.flip_low_power_fallback'"),'publisher Reader settings registered');
$ok(str_contains($app,'data-default-view=')&&str_contains($app,'data-flip-duration=')&&str_contains($app,"reader.flip_shadow"),'Reader settings reach rendered reader shell');
$ok(str_contains($view,"/assets/reader.js")&&str_contains($view,"/assets/reader-flip.js"),'Reader adapter is versioned and loaded after core Reader');
$ok(str_contains($css,'.reader-flip-book')&&str_contains($css,'.reader-view-continuous')&&str_contains($css,'.reader-turn-shadow'),'flip/spread/continuous CSS packaged');
$ok(str_contains($android,"versionName '2.0.2.0'")&&str_contains($android,'versionCode 20200')&&str_contains($main,'EPDI-Android/2.0.2.0'),'Android wrapper version aligned');
$ok(!is_file($root.'/database/upgrade-v2.0.2.0.sql'),'no v2.0.2.0 database migration');
if($fails){fwrite(STDERR,"FAIL\n - ".implode("\n - ",$fails)."\n");exit(1);}echo"\nPASS v2.0.2.0 realistic newspaper reader guard\n";
